package net.javaguides.order_service.entity;

import jakarta.persistence.*;
import lombok.*;

import java.math.BigDecimal;

/**
 * Line of an {@link Order}. Created only through {@link Order#addItem}; the id is always generated by the DB.
 */
@NoArgsConstructor(access = AccessLevel.PROTECTED) // for JPA
@Getter
@Entity
@Table(name = "order_items")
public class OrderItem {
    @Id
    @GeneratedValue(strategy =  GenerationType.IDENTITY)
    private Long id;

    @ManyToOne
    @JoinColumn(name = "order_id")
    private Order order;

    private String productId;

    private Integer quantity;

    private BigDecimal price;

    private String variantId;

    private String color;

    static OrderItem of(Order order, String productId, Long variantId, Integer quantity, BigDecimal price, String color) {
        OrderItem item = new OrderItem();
        item.order = order;
        item.productId = productId;
        item.variantId = variantId == null ? null : String.valueOf(variantId);
        item.quantity = quantity;
        item.price = price;
        item.color = color;
        return item;
    }

    BigDecimal lineTotal() {
        return price.multiply(BigDecimal.valueOf(quantity));
    }
}
